/* Документы «Фруктовый Дом» — собрано автоматически, не редактировать вручную */
(function(){var r=document.getElementById("fd-root");if(!r){r=document.createElement("div");r.id="fd-root";document.body.appendChild(r);}r.innerHTML="<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Golos+Text:wght@400;500;600;700&display=swap\">\n<style>#fd-app{--bg:#F4F6F4;--surface:#FFFFFF;--ink:#1C2220;--muted:#65706A;--line:#DCE2DE;--accent:#6A2C4E;--accent-ink:#FFFFFF;--accent-soft:#F2E7ED;--warn:#9A5B00;--warn-soft:#FFF4E0;--ok:#2F6B45;--err:#B3261E;--ui:\"Golos Text\", system-ui, -apple-system, \"Segoe UI\", Roboto, Arial, sans-serif;background:var(--bg);color:var(--ink);font:15px/1.45 var(--ui);font-variant-numeric:tabular-nums;min-height:100vh;text-align:left;color-scheme:light}#fd-app *{box-sizing:border-box}#fd-app [hidden]{display:none!important}#fd-app .wrap{max-width:1040px;margin:0 auto;padding-left:max(16px,env(safe-area-inset-left,0));padding-right:max(16px,env(safe-area-inset-right,0));padding-block:0 48px}#fd-app header.top{position:sticky;top:0;z-index:50;background:var(--bg);border-bottom:1px solid var(--line)}#fd-app header.top .wrap{padding-block:12px 0}#fd-app .brand{display:flex;align-items:center;gap:10px;flex-wrap:wrap}#fd-app .brand b{font-size:18px;letter-spacing:-.01em}#fd-app .brand .sub{color:var(--muted);font-size:13px}#fd-app .status{margin-left:auto;display:inline-flex;align-items:center;gap:6px;font-size:12px;color:var(--muted);padding:4px 10px;border-radius:99px;background:var(--surface);border:1px solid var(--line);cursor:pointer}#fd-app .status i{width:8px;height:8px;border-radius:50%;background:var(--muted);display:inline-block}#fd-app .status[data-s=ok] i{background:var(--ok)}#fd-app .status[data-s=saving] i,#fd-app .status[data-s=wait] i{background:var(--warn)}#fd-app .status[data-s=err]{color:var(--err);border-color:var(--err)}#fd-app .status[data-s=err] i{background:var(--err)}#fd-app nav.tabs{display:flex;gap:4px;overflow-x:auto;margin-top:8px;scrollbar-width:none}#fd-app nav.tabs button{border:0;background:0 0;color:var(--muted);font:500 14px var(--ui);padding:10px 12px;border-bottom:2px solid transparent;cursor:pointer;white-space:nowrap;border-radius:0}#fd-app nav.tabs button[aria-selected=true]{color:var(--ink);border-bottom-color:var(--accent)}#fd-app section.tab{display:grid;gap:16px;margin-top:20px}#fd-app .card{background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:16px;display:grid;gap:12px;min-width:0}#fd-app .card h2{margin:0;font:600 15px var(--ui);color:var(--ink)}#fd-app .card h2 small{font-weight:400;color:var(--muted);margin-left:6px}#fd-app .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px 14px}#fd-app label.f{display:grid;gap:4px;font-size:12px;color:var(--muted);letter-spacing:.02em;min-width:0;margin:0}#fd-app label.f.wide{grid-column:1/-1}#fd-app textarea{resize:vertical;font-size:14px}#fd-app input,#fd-app select,#fd-app textarea{font:15px var(--ui);color:var(--ink);background:var(--bg);border:1px solid var(--line);border-radius:7px;padding:9px 10px;width:100%;min-width:0;height:auto;margin:0;box-shadow:none}#fd-app input:focus,#fd-app select:focus,#fd-app button:focus-visible{outline:2px solid var(--accent);outline-offset:1px}#fd-app .btn{font:500 14px var(--ui);border-radius:8px;padding:9px 14px;border:1px solid var(--line);background:var(--surface);color:var(--ink);cursor:pointer;line-height:1.2}#fd-app .btn:hover{border-color:var(--muted)}#fd-app .btn.pri{background:var(--accent);color:var(--accent-ink);border-color:var(--accent)}#fd-app .btn.ghost{background:0 0;border-color:transparent;color:var(--muted)}#fd-app .btn.danger{color:var(--err)}#fd-app .btn.sm{padding:5px 9px;font-size:13px}#fd-app .btn[disabled]{opacity:.6;cursor:progress}#fd-app .row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}#fd-app .muted{color:var(--muted);font-size:13px}#fd-app p{margin:0}#fd-app .note{background:var(--warn-soft);color:var(--warn);border-radius:8px;padding:10px 12px;font-size:13px}#fd-app .lines{display:grid;gap:8px}#fd-app .line{display:grid;grid-template-columns:minmax(0,1fr) 90px 44px 110px 110px 36px;gap:8px;align-items:center}#fd-app .line .unit{color:var(--muted);font-size:13px}#fd-app .line .sum{text-align:right;font-weight:500}#fd-app .line .x{border:0;background:0 0;color:var(--muted);font-size:20px;cursor:pointer;padding:4px}#fd-app .lines .head{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em}#fd-app .line input.price.custom{border-color:var(--accent)}@media (max-width:640px){#fd-app .line{grid-template-columns:1fr 1fr 36px;grid-template-areas:\"p p x\"\"q pr pr\"\"u s s\";background:var(--bg);padding:8px;border-radius:8px}#fd-app .line .prod{grid-area:p}#fd-app .line .qty{grid-area:q}#fd-app .line .price{grid-area:pr}#fd-app .line .unit{grid-area:u}#fd-app .line .sum{grid-area:s}#fd-app .line .x{grid-area:x}#fd-app .lines .head{display:none}}#fd-app .totals{display:flex;justify-content:flex-end;gap:24px;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:10px}#fd-app .totals div{text-align:right}#fd-app .totals b{display:block;font-size:20px;color:var(--ink)}#fd-app .make{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}#fd-app .make .btn{padding:14px 8px;font-size:15px}#fd-app .make2{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}#fd-app .make2 .btn{padding:12px 8px}#fd-app .make2 .btn small{display:block;font-weight:400;font-size:11px;opacity:.8}#fd-app .dl{font-size:12px;color:var(--ok);white-space:nowrap}#fd-app .make .btn small{display:block;font-weight:400;font-size:11px;opacity:.8}#fd-app .tbl{overflow-x:auto}#fd-app .tbl table.order{min-width:0}#fd-app table.order td.a{min-width:160px}#fd-app table.order td.a small{display:block;color:var(--muted);font-size:12px;line-height:1.3}#fd-app table.order input.q{width:84px;text-align:right}#fd-app table.order th.num,#fd-app table.order td.num{text-align:right;white-space:nowrap}#fd-app table.order tfoot td{font-weight:600;border-bottom:0}@media (max-width:700px){#fd-app table.order td.a{min-width:92px;font-size:13px}#fd-app table.order td.a small{font-size:11px}#fd-app table.order input.q{width:56px;padding:6px 4px}#fd-app table.order th,#fd-app table.order th.num{font-size:10px;letter-spacing:0;padding:4px;white-space:normal}#fd-app table.order td{padding:4px 3px}}#fd-app .chk{display:inline-flex;gap:6px;align-items:center;font-size:15px;margin-right:18px;cursor:pointer}#fd-app .chk input{width:18px;height:18px}#fd-app .done{margin-top:10px;display:grid;gap:6px}#fd-app .done div{display:flex;gap:8px;align-items:center;flex-wrap:wrap;font-size:14px}#fd-app .tbl table{border-collapse:collapse;width:100%;min-width:560px}#fd-app .tbl th{font:500 11px var(--ui);color:var(--muted);text-transform:uppercase;letter-spacing:.06em;text-align:left;padding:6px;border-bottom:1px solid var(--line)}#fd-app .tbl td{padding:4px 6px;border-bottom:1px solid var(--line);vertical-align:middle;font-size:14px}#fd-app .tbl td input,#fd-app .tbl td select{padding:6px 8px;font-size:14px}#fd-app .tbl td.num{text-align:right;white-space:nowrap}#fd-app .tbl .acts{white-space:nowrap;text-align:right}#fd-app .ctrinfo{font-size:12px;color:var(--muted);letter-spacing:0}#fd-app .ctrinfo.warn{color:var(--err)}@media (max-width:700px){#fd-app table.stack{min-width:0!important}#fd-app table.stack thead{display:none}#fd-app table.stack tbody tr{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 10px;padding:12px 0;border-bottom:1px solid var(--line)}#fd-app table.stack td{display:block;border:0;padding:0;min-width:0;text-align:left!important;white-space:normal}#fd-app table.stack td[data-label]::before{content:attr(data-label);display:block;font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;margin-bottom:3px}#fd-app table.stack td.full{grid-column:1/-1}#fd-app table.stack td.acts{display:flex;flex-wrap:wrap;gap:6px;white-space:normal}#fd-app table.stack td.acts .btn{padding:8px 12px}#fd-app .make{grid-template-columns:1fr 1fr 1fr}#fd-app .make2{grid-template-columns:1fr}#fd-app .modal .bar{gap:6px}#fd-app .modal .bar b{flex-basis:100%;font-size:14px}#fd-app .modal .bar .btn{padding:8px 10px;font-size:13px}#fd-app .modal .paper{padding:8px}}#fd-app .login{max-width:420px;margin:60px auto}#fd-app .modal{position:fixed;inset:0;z-index:99990;background:rgba(10,12,11,.88);display:flex;flex-direction:column}#fd-app .modal .bar{background:var(--surface);display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:10px max(16px,env(safe-area-inset-right,0)) 10px max(16px,env(safe-area-inset-left,0));padding-top:calc(10px + env(safe-area-inset-top,0))}#fd-app .modal .bar b{margin-right:auto}#fd-app .modal .paper{overflow:auto;flex:1;padding:16px}#fd-app .modal .warns{padding:8px 16px;background:var(--warn-soft);color:var(--warn);font-size:13px}#fd-app .sheet{background:#fff;color:#000;margin:0 auto 16px;box-shadow:0 2px 14px rgba(0,0,0,.25);padding:8mm}#fd-app #pv-pages.snap .sheet{box-shadow:none}#fd-app .sheet.portrait{width:210mm;min-height:297mm}#fd-app .sheet.landscape{width:297mm;min-height:210mm}</style>\n<style id=\"fd-doc-css\">.doc{font-family:Arial,\"Liberation Sans\",Helvetica,sans-serif;color:#000;font-size:8pt;line-height:1.2}.doc table{border-collapse:collapse;width:100%}.doc .g td,.doc .g th{border:1px solid #000;padding:2px 3px;vertical-align:top}.doc .g th{font-weight:400;text-align:center;vertical-align:middle}.doc .r{text-align:right;white-space:nowrap}.doc .c{text-align:center}.doc .b{font-weight:700}.doc .sm{font-size:6.5pt}.doc .u{border-bottom:1px solid #000;min-height:11pt}.doc .sig .u{white-space:nowrap}.doc .cap{font-size:6pt;text-align:center;color:#000}.doc h1{font-size:13pt;margin:10px 0 4px}.doc hr.thick{border:0;border-top:2px solid #000;margin:6px 0}.doc .lbl td{padding:2px 4px;vertical-align:bottom}.doc-invoice{font-size:9pt}.doc-invoice .g td{padding:3px 5px}.doc .sig{display:grid;grid-template-columns:auto 1fr 8px 1fr;align-items:end;gap:0 4px;margin-top:4px}.doc .nobr{white-space:nowrap}.doc .lab{width:1%;white-space:nowrap;padding-right:4px;vertical-align:top;padding-top:3px}.doc .lbl td{vertical-align:top}.doc .codes{border-collapse:collapse;margin-top:2px}.doc .codes td{padding:1px 3px;height:15px}.doc .codes .box,.doc .bx td,.doc .bx th{border:1px solid #000;width:38%}.doc .codes tr:nth-child(2) .box{border:1.5px solid #000}.doc .pgno{text-align:right;font-style:italic;font-size:7.5pt;margin:2px 0}.doc .items{font-size:7pt}.doc .items td{padding:1px 2px;vertical-align:top}.doc .items tr.nums th{font-size:6.5pt;padding:0}.doc .items thead{display:table-header-group}.doc .tot td{border:1px solid #000}.doc .tot td.nb{border:0}.doc .s3{display:grid;grid-template-columns:24% 22% 18% 1fr;gap:0 8px;align-items:end;margin-top:7px}.doc .s4{display:grid;grid-template-columns:1fr 1fr 1.3fr auto;gap:0 6px;align-items:end;margin:3px 0 5px}.doc .ib{display:inline-block;min-width:60px;vertical-align:bottom}.doc .mp{display:flex;gap:90px;margin:12px 0 0 90px}.doc .t12f{margin-top:6px}.doc .t12f td{padding:1px 2px;vertical-align:bottom}.doc .updleft{width:14%;vertical-align:top;border-right:2px solid #000;padding-right:6px}.doc .updh td{padding:0 2px;vertical-align:bottom}.doc .updh td.v{width:100%}.doc .updh td.n{width:1%}.doc .updh .lab{white-space:normal;min-width:120px;max-width:300px;width:auto}.doc .updh.fx{table-layout:fixed}.doc .updh.fx td.lab{white-space:normal;width:auto;max-width:none;min-width:0}.doc .updh td.lab.nobr{white-space:nowrap;min-width:0;max-width:none}.doc .upd2{margin-top:4px}.doc .upd2 td{vertical-align:top;width:50%}.doc .upd2 td.l{border-right:1px solid #000;padding-right:8px}.doc .upd2 td.r2{padding-left:8px}.doc .upd2 .dl{margin:3px 0}.doc .mpu{margin-top:4px;padding-left:40px}.doc.upd{font-size:7.5pt}.doc.upd .items{font-size:6.5pt}</style> <div id=\"fd-app\"><header class=\"top\"><div class=\"wrap\"><div class=\"brand\"><b>Фруктовый Дом · документы</b><span class=\"sub\">счёт · ТОРГ‑12 · УПД</span><button class=\"status\" id=\"fd-status\" data-s=\"local\" title=\"Нажмите, чтобы обновить данные\"><i></i><span>На этом устройстве</span></button></div><nav class=\"tabs\" role=\"tablist\"><button data-tab=\"doc\" aria-selected=\"true\">Новый документ</button><button data-tab=\"order\">Заявка</button><button data-tab=\"journal\">Журнал</button><button data-tab=\"customers\">Заказчики и цены</button><button data-tab=\"products\">Товары</button><button data-tab=\"suppliers\">Поставщики</button><button data-tab=\"data\">Данные</button></nav></div></header><main class=\"wrap\"><div class=\"card login\" id=\"fd-login\" hidden><h2>Вход</h2><p class=\"muted\">Введите пароль, который задан в Google Таблице‑хранилище. На этом компьютере он запомнится.</p><label class=\"f\">Пароль<input id=\"fd-pass\" type=\"password\" autocomplete=\"current-password\"></label><div class=\"row\"><button class=\"btn pri\" id=\"fd-enter\">Войти</button><span class=\"muted\" id=\"fd-loginmsg\"></span></div></div><div id=\"fd-main\"><div id=\"demoNote\" class=\"note\" style=\"margin-top:16px\" hidden>Реквизиты, товары и цены заполнены для примера. Замените их на свои во вкладках «Поставщики», «Товары» и «Заказчики и цены». <button class=\"btn ghost sm\" id=\"hideDemo\">Понятно</button></div><section class=\"tab\" id=\"tab-doc\"><div class=\"card\"><h2>Стороны <small id=\"d-editing\"></small></h2><div class=\"grid\"><label class=\"f\">Поставщик<select id=\"d-sup\"></select></label><label class=\"f\">Заказчик<select id=\"d-cus\"></select></label><label class=\"f wide\" id=\"d-brwrap\" hidden>Обособленное подразделение (покупатель и грузополучатель)<select id=\"d-br\"></select></label><label class=\"f wide\">Контракт / договор<select id=\"d-ctr\"></select><span id=\"d-ctrinfo\" class=\"ctrinfo\"></span></label><label class=\"f\">Номер документа<input id=\"d-num\" inputmode=\"numeric\"></label><label class=\"f\">Дата<input id=\"d-date\" type=\"date\"></label><label class=\"f wide\">Основание (договор, контракт)<input id=\"d-basis\" placeholder=\"ЭЗК-26-91390881 от 30.09.2026\"></label><label class=\"f wide\">Адрес доставки (грузополучатель)<select id=\"d-shipsel\"></select></label><label class=\"f wide\" id=\"d-shipwrap\">Другой адрес<input id=\"d-ship\" placeholder=\"Впишите адрес доставки\"></label></div></div><div class=\"card\"><h2>Товары <small id=\"d-pricehint\"></small></h2><div class=\"lines\" id=\"d-lines\"></div><div class=\"row\"><button class=\"btn\" id=\"d-add\">+ Добавить товар</button><button class=\"btn ghost\" id=\"d-addall\">Добавить весь прайс заказчика</button></div><div class=\"totals\" id=\"d-totals\"></div></div><div class=\"card\"><h2>Сформировать <small>документ сохранится в журнал</small></h2><div class=\"make\"><button class=\"btn pri\" data-make=\"invoice\">Счёт<small>на оплату</small></button><button class=\"btn pri\" data-make=\"torg12\">ТОРГ‑12<small>товарная накладная</small></button><button class=\"btn pri\" data-make=\"upd\">УПД<small>универсальный</small></button></div><div class=\"make2\"><button class=\"btn\" data-combo=\"invoice,torg12\">Скачать счёт + ТОРГ‑12<small>одним PDF</small></button><button class=\"btn\" data-combo=\"invoice,upd\">Скачать счёт + УПД<small>одним PDF</small></button></div><div class=\"row\"><button class=\"btn ghost\" id=\"d-new\">Очистить и начать новый</button><span class=\"muted\" id=\"d-saved\"></span></div></div></section><section class=\"tab\" id=\"tab-order\" hidden><div class=\"card\"><h2>Заявка → документы <small>на каждый адрес доставки — своя накладная</small></h2><div class=\"grid\"><label class=\"f\">Заказчик<select id=\"o-cus\"></select></label><label class=\"f\">Поставщик<select id=\"o-sup\"></select></label><label class=\"f wide\" id=\"o-brwrap\" hidden>Обособленное подразделение<select id=\"o-br\"></select></label><label class=\"f\">Дата документов (день поставки)<input id=\"o-date\" type=\"date\"></label><label class=\"f\">Основание<input id=\"o-basis\" readonly></label></div><p class=\"muted\" id=\"o-ctrinfo\"></p></div><div class=\"card\"><h2>Количество по адресам <small>впишите цифры из заявки, пустые строки пропускаются</small></h2><div class=\"tbl\"><table class=\"order\"><thead id=\"o-head\"></thead><tbody id=\"o-body\"></tbody><tfoot id=\"o-foot\"></tfoot></table></div><div class=\"row\"><button class=\"btn ghost\" id=\"o-addaddr\">+ Другой адрес</button><button class=\"btn ghost\" id=\"o-clear\">Очистить количества</button></div></div><div class=\"card\"><h2>Что скачать</h2><div class=\"row\"><label class=\"chk\"><input type=\"checkbox\" id=\"o-k-invoice\" checked>Счёт</label><label class=\"chk\"><input type=\"checkbox\" id=\"o-k-torg12\" checked>ТОРГ‑12</label><label class=\"chk\"><input type=\"checkbox\" id=\"o-k-upd\">УПД</label></div><div class=\"row\"><button class=\"btn pri\" id=\"o-go\">Создать документы и скачать PDF</button><span class=\"muted\" id=\"o-msg\"></span></div><div class=\"done\" id=\"o-done\"></div></div></section><section class=\"tab\" id=\"tab-journal\" hidden><div class=\"card\"><h2>Журнал документов <small id=\"jr-count\"></small></h2><div class=\"row\"><input id=\"jr-q\" placeholder=\"Поиск: заказчик, номер, поставщик\" style=\"max-width:360px\"><button class=\"btn ghost\" id=\"jr-refresh\">Обновить</button></div><p class=\"muted\">Кнопки Счёт / ТОРГ‑12 / УПД открывают документ ровно в том виде, в каком он был создан: с теми реквизитами и ценами. Скачать PDF — кнопкой «Печать / PDF», затем «Сохранить как PDF».</p><div class=\"tbl\"><table class=\"stack\" data-full=\"2,3,6\"><thead><tr><th>Дата</th><th>№</th><th>Поставщик</th><th>Заказчик</th><th class=\"num\">Сумма</th><th>Скачан</th><th class=\"acts\"></th></tr></thead><tbody id=\"jr-body\"></tbody></table></div></div></section><section class=\"tab\" id=\"tab-customers\" hidden><div class=\"card\" id=\"cus-editor\"></div><div class=\"card\"><h2>Обособленные подразделения <small id=\"br-name\"></small></h2><p class=\"muted\">Если заказчик принимает и оплачивает товар через разные ОП (свой КПП, адрес, лицевой счёт), заведите их здесь. В документе появится выбор подразделения, и в счёте, ТОРГ‑12 и УПД будут реквизиты выбранного ОП.</p><div id=\"br-list\" style=\"display:grid;gap:12px\"></div><div class=\"row\"><button class=\"btn\" id=\"br-add\">+ Добавить подразделение</button></div></div><div class=\"card\"><h2>Контракты и договоры <small id=\"ct-name\"></small></h2><p class=\"muted\">Каждый контракт привязан к конкретному исполнителю. В документе при выборе контракта поставщик, основание и ИКЗ подставятся сами, а по цене контракта считается остаток.</p><div class=\"tbl\"><table class=\"stack\" data-full=\"0,1,2\"><thead><tr><th style=\"width:190px\">Исполнитель</th><th>Основание (номер и дата)</th><th style=\"width:170px\">ИКЗ</th><th style=\"width:120px\">Цена контракта</th><th style=\"width:140px\">Действует до</th><th class=\"num\">Отгружено</th><th style=\"width:40px\"></th></tr></thead><tbody id=\"ct-body\"></tbody></table></div><div class=\"row\"><button class=\"btn\" id=\"ct-add\">+ Добавить контракт</button></div></div><div class=\"card\"><h2>Цены для заказчика <small id=\"pr-name\"></small></h2><p class=\"muted\">Пустая цена — товара нет в прайсе заказчика, в документ подставится базовая цена. Товары общие для всех заказчиков, цены у каждого свои.</p><div class=\"row\"><select id=\"pr-copyfrom\" style=\"max-width:320px\"></select><button class=\"btn\" id=\"pr-copy\">Скопировать цены</button></div><div class=\"tbl\"><table class=\"stack\" data-full=\"0\"><thead><tr><th>Товар</th><th>Ед.</th><th class=\"num\">Базовая</th><th style=\"width:130px\">Цена заказчика</th><th style=\"width:150px\">ID позиции спец. (СПГЗ)</th><th style=\"width:120px\">ID СТЕ</th><th style=\"width:150px\">Артикул оферты</th></tr></thead><tbody id=\"pr-body\"></tbody></table></div></div><div class=\"card\"><h2>Сопоставить с Порталом поставщиков <small id=\"pp-name\"></small></h2><p class=\"muted\">Нужно один раз на контракт, чтобы выгружать УПД в XML. На Портале поставщиков откройте контракт → блок «Сведения о спецификациях» → «Выгрузить в xls», и загрузите этот файл сюда — позиции сопоставятся с вашими товарами по цене. ID СТЕ подтягиваются из УПД, уже отправленных через Портал: загрузите сюда XML такого документа.</p><div class=\"row\"><label class=\"btn\">Загрузить выгрузку (.xlsx) или отправленный УПД (.xml)<input type=\"file\" id=\"pp-file\" accept=\".xlsx,.xls,.csv,.xml,.txt\" hidden></label><span class=\"muted\" id=\"pp-msg\"></span></div><div class=\"tbl\" id=\"pp-wrap\" hidden><table class=\"stack\" data-full=\"0,5\"><thead><tr><th>Позиция в Портале</th><th style=\"width:110px\">ID спец.</th><th style=\"width:100px\">ID СТЕ</th><th style=\"width:130px\">Артикул</th><th class=\"num\" style=\"width:90px\">Цена</th><th style=\"width:280px\">Ваш товар</th></tr></thead><tbody id=\"pp-body\"></tbody></table></div><div class=\"row\" id=\"pp-act\" hidden><button class=\"btn pri\" id=\"pp-save\">Сохранить сопоставление</button></div></div><div class=\"card\"><h2>Загрузить прайс из таблицы <small id=\"im-name\"></small></h2><p class=\"muted\">Выделите в Google Таблице или Excel строки с товарами вместе с заголовком (нужны колонки «Товар» или «Наименование», «Ед.» и «Цена»), скопируйте и вставьте сюда. Новые товары добавятся в номенклатуру, цены запишутся этому заказчику. Существующие товары узнаются по названию.</p><textarea id=\"im-text\" rows=\"6\" placeholder=\"Товар&#9;Ед.&#9;Цена&#10;Курага (без косточки)&#9;кг&#9;714,96\"></textarea><div class=\"row\"><button class=\"btn pri\" id=\"im-go\">Добавить в прайс заказчика</button><span class=\"muted\" id=\"im-msg\"></span></div></div></section><section class=\"tab\" id=\"tab-products\" hidden><div class=\"card\"><h2>Номенклатура <small>общая для всех поставщиков и заказчиков</small></h2><div class=\"tbl\"><table class=\"stack\" data-full=\"0\"><thead><tr><th>Наименование</th><th style=\"width:130px\">Код (артикул)</th><th style=\"width:90px\">Ед.</th><th style=\"width:150px\">Страна</th><th style=\"width:120px\">Базовая цена</th><th style=\"width:40px\"></th></tr></thead><tbody id=\"pd-body\"></tbody></table></div><div class=\"row\"><button class=\"btn\" id=\"pd-add\">+ Новый товар</button></div></div></section><section class=\"tab\" id=\"tab-suppliers\" hidden><div class=\"card\" id=\"sup-editor\"></div></section><section class=\"tab\" id=\"tab-data\" hidden><div class=\"card\"><h2>Хранилище</h2><p class=\"muted\" id=\"dt-store\"></p><div class=\"row\"><button class=\"btn\" id=\"dt-pull\">Обновить данные с сервера</button><button class=\"btn ghost\" id=\"dt-logout\">Выйти на этом компьютере</button></div></div><div class=\"card\"><h2>Резервная копия</h2><p class=\"muted\">Файл со всеми справочниками и журналом. Пригодится как запасная копия.</p><div class=\"row\"><button class=\"btn pri\" id=\"dt-export\">Скачать данные (.json)</button><label class=\"btn\">Загрузить из файла<input type=\"file\" id=\"dt-import\" accept=\".json,application/json\" hidden></label></div><p class=\"muted\" id=\"dt-msg\"></p></div></section></div></main><div class=\"modal\" id=\"pv\" hidden><div class=\"bar\"><b id=\"pv-title\"></b><button class=\"btn\" id=\"pv-xml\" hidden>XML для Портала поставщиков</button><button class=\"btn\" id=\"pv-edo\" hidden>XML для Диадок (ФНС)</button><button class=\"btn pri\" id=\"pv-pdf\">Скачать PDF</button><button class=\"btn\" id=\"pv-print\">Печать</button><button class=\"btn\" id=\"pv-close\">Закрыть</button></div><div class=\"warns\" id=\"pv-warn\" hidden></div><div class=\"paper\" id=\"pv-pages\"></div></div><div id=\"fd-measure\" aria-hidden=\"true\" style=\"position:absolute;left:-9999px;top:0;width:281mm;visibility:hidden\"></div></div>";})();
